<script setup lang="ts">
const props=defineProps<{roleId?:number;create?:boolean}>()
const {t}=useI18n(),{roleLabel}=useOptionLabel(),{bizErrorMessage}=useBizError(),router=useRouter()
const roles=ref<any[]>([]),permissions=ref<any[]>([]),record=ref<any>(null),loading=ref(true),saving=ref(false),keyword=ref(''),error=ref(''),nameError=ref('')
const label=(row:any)=>row?.display_name||roleLabel(row?.name)
const companyOwned=computed(()=>record.value?.company_id!=null)
const form=reactive({name:'',description:'',permissions:[] as number[],is_active:true})
const filtered=computed(()=>roles.value.filter(row=>(row.name+' '+row.description+' '+label(row)).toLowerCase().includes(keyword.value.toLowerCase())))
const original=ref<string|null>(null),saveError=ref('')
const snapshot=()=>JSON.stringify(form)
useUnsavedForm(()=>!companyOwned.value&&!loading.value&&original.value!==null&&snapshot()!==original.value,()=>saving.value)
let generation=0
const load=async()=>{
 const seq=++generation;loading.value=true;error.value='';saveError.value='';record.value=null;original.value=null
 if(props.create){form.name='';form.description='';form.permissions=[];form.is_active=true;nameError.value=''}
 const onError=(e:any)=>{if(seq===generation)error.value=bizErrorMessage(e)}
 const loadCatalog=async(url:string)=>{const items:any[]=[];let page=1;while(true){const data=await httpRequest<PaginationData>(url,{params:{page,per_page:100},onError});if(seq!==generation||!data)return null;items.push(...(data.items||[]));if(items.length>=data.total||!data.items?.length)return {...data,items};page++}}
 const results=await Promise.all([loadCatalog('/api/system/user/roles'),loadCatalog('/api/system/user/permissions')])
 if(seq!==generation)return
 roles.value=results[0]?.items||[];permissions.value=results[1]?.items||[]
 if(!results[0]||!results[1]){loading.value=false;return}
 if(!props.create){const id=props.roleId||roles.value[0]?.id;if(id){const value=await httpRequest<any>('/api/system/user/roles/'+id,{onError});if(seq!==generation)return;record.value=value;if(value){form.is_active=value.is_active!==false;form.name=value.display_name||value.name;form.description=value.description||'';form.permissions=permissions.value.filter(p=>(value.permissions||[]).includes(p.name)).map(p=>p.id)}}}
 original.value=snapshot();loading.value=false
}
const save=async()=>{if(saving.value||loading.value||error.value||companyOwned.value||(!props.create&&!record.value))return;saveError.value='';nameError.value=form.name.trim()?'':t('common.validation.name-required',{entity:t('common.entities.role')});if(nameError.value)return;saving.value=true;let saved:any=null;await httpRequest<any>('/api/system/user/roles'+(props.create?'':'/'+record.value.id),{method:props.create?'POST':'PUT',body:{name:form.name.trim(),description:form.description,permissions:form.permissions,is_active:form.is_active},onSuccess:data=>{saved=data},onError:e=>{saveError.value=bizErrorMessage(e);showToast(saveError.value,'error')}});if(saved){original.value=snapshot();showToast(t('action-results.success'),'success');if(props.create&&saved.id)await router.push('/admin/roles/'+saved.id);else await load()}saving.value=false}
const remove=async()=>{if(!record.value||record.value.is_builtin||companyOwned.value||saving.value)return;if(!await showConfirm(t('action-results.delete-confirm-title'),t('action-results.delete-confirm',{entity:t('common.entities.role')}),t('button.confirm'),t('button.cancel')))return;saving.value=true;let deleted=false;await httpRequest('/api/system/user/roles/'+record.value.id,{method:'DELETE',onSuccess:()=>{deleted=true},onError:e=>{saveError.value=bizErrorMessage(e);showToast(saveError.value,'error')}});saving.value=false;if(deleted){original.value=snapshot();await router.push('/admin/roles')}}
const reset=async()=>{if(saving.value||loading.value)return;if(original.value!==null&&snapshot()!==original.value&&!await wConfirm({title:t('unsaved-form.title'),message:t('unsaved-form.message'),confirmText:t('unsaved-form.leave'),cancelText:t('unsaved-form.stay')}))return;await load()}
onMounted(load)
onBeforeUnmount(()=>generation++)
useHead({title:()=>t('admin.nav.roles')})
</script>
<template><div class="w-role-manager w-scope"><header><h1>{{t('admin.nav.roles')}}</h1><WButton variant="primary" to="/admin/roles/add">{{t('admin.roles.operations.add')}}</WButton></header><WAlert v-if="error" tone="block" :title="error"><template #actions><WButton @click="load">{{t('dn.list.retry')}}</WButton></template></WAlert><WAlert v-if="saveError" tone="block" :title="saveError"/><div class="role-grid"><WCard flush><div class="search"><WInput v-model="keyword" type="search" :aria-label="t('common.search')" :placeholder="t('common.search-placeholder')"><template #prefix><WIcon name="search" :size="16"/></template></WInput></div><nav class="role-list"><NuxtLink v-for="row in filtered" :key="row.id" class="w-role-link" :class="{selected:record?.id===row.id}" :to="'/admin/roles/'+row.id"><strong>{{label(row)}}</strong><code v-if="label(row)!==row.name">{{row.name}}</code><small>{{row.description}}</small><small>{{t("admin-role-scope.usage",{users:row.user_count??'—',permissions:row.permissions?.length??0})}}</small><WStatus v-if="row.is_active===false" tone="none">{{t("common.status.inactive")}}</WStatus><small v-if="row.company_id!=null">{{t('admin-role-scope.company',{id:row.company_id})}}</small><span v-if="row.is_builtin" class="builtin">{{t('admin.builtin.label')}}</span></NuxtLink></nav></WCard><WCard flush><div class="form-heading"><h2>{{create?t('admin.roles.operations.add'):label(record)}}</h2><span v-if="record?.is_builtin" class="builtin">{{t('admin.builtin.label')}}</span></div><WEmptyState v-if="loading" :title="t('common.status.loading')"/><form v-else-if="create||record" @submit.prevent="save"><WAlert v-if="companyOwned" tone="info" :title="t('admin-role-scope.readonly')"/><fieldset :disabled="saving||!!error||companyOwned"><section class="form-section"><div class="fields"><WField :label="t('common.fields.name')" required :error="nameError" :hint="record?.is_builtin?t('admin.builtin.role-tip'):undefined"><WInput v-model="form.name" :readonly="record?.is_builtin"/></WField><WField :label="t('common.fields.description')"><WInput v-model="form.description"/></WField><WSwitch v-model="form.is_active" :disabled="record?.is_builtin">{{t('recipient.ui.enable')}}</WSwitch></div></section><section class="permissions"><PermissionSelector matrix :all-permissions="permissions" v-model="form.permissions"/></section></fieldset><footer><WButton v-if="record&&!record.is_builtin&&!companyOwned" variant="danger" :disabled="saving" @click="remove">{{t('button.delete')}}</WButton><WButton :disabled="saving" @click="reset">{{t('button.reset')}}</WButton><WButton v-if="!companyOwned" type="submit" variant="primary" :loading="saving" :disabled="!!error">{{t('button.save')}}</WButton></footer></form></WCard></div></div></template>
<style scoped>
.w-role-manager{min-width:0;display:flex;flex-direction:column;gap:16px}header{display:flex;align-items:center;justify-content:space-between;gap:12px}h1{font-size:24px;line-height:32px;font-weight:600;margin:0}.role-grid{display:grid;grid-template-columns:256px minmax(0,1fr);gap:16px;align-items:start}.search{padding:12px;border-bottom:1px solid var(--w-line)}.role-grid>:deep(.w-card){min-width:0}.role-list{padding:8px;display:flex;flex-direction:column;gap:2px}.w-role-link{min-width:0;overflow-wrap:anywhere;display:flex;flex-wrap:wrap;align-items:center;gap:2px 8px;padding:8px 12px;border-radius:6px;color:var(--w-text-1);text-decoration:none}.w-role-link.selected{background:#F5F4FF;color:#4E1DBC}.w-role-link strong{font-size:14px;line-height:22px;font-weight:500}.w-role-link.selected strong{font-weight:600}code,small{font-size:12px;line-height:18px;color:var(--w-text-3)}small{flex-basis:100%}.builtin{display:inline-block;padding:1px 6px;border:1px solid var(--w-border);border-radius:6px;font-size:12px;line-height:16px;color:var(--w-text-2)}.form-heading{display:flex;align-items:center;flex-wrap:wrap;gap:12px;padding:16px 24px 4px}h2{overflow-wrap:anywhere;min-width:0;font-size:16px;line-height:24px;font-weight:600;margin:0}h3{font-size:14px;line-height:22px;font-weight:600;margin:0}fieldset{border:0;padding:0;margin:0;min-width:0}.form-section{padding:12px 24px 20px}.fields{display:grid;grid-template-columns:1fr 2fr;gap:12px 16px}.fields>.w-switch{grid-column:1/-1}.permissions{padding:0}footer{display:flex;justify-content:flex-end;gap:8px;padding:16px 24px;border-top:1px solid var(--w-border)}@media(max-width:1100px){.role-grid{grid-template-columns:minmax(0,1fr)}.role-list{max-height:240px;overflow:auto}.form-section{grid-template-columns:minmax(0,1fr);gap:16px}}
@media(max-width:600px){.fields{grid-template-columns:minmax(0,1fr)}header,footer{flex-wrap:wrap}}
</style>
